/**
 * As medidas da Bíblia — porte de `componentes/viz/medidas_biblia.js`.
 *
 * O que trava a pessoa não é a tabela de conversão do apêndice B14-A: é que "300
 * côvados" não vira imagem nenhuma na cabeça. Então cada fase desenha a medida
 * bíblica AO LADO de algo cujo tamanho todo mundo já conhece, na mesma escala:
 *
 * - `covado`  → o antebraço desenhado de verdade, com a régua do cotovelo à ponta
 *               do dedo médio (44,5 cm).
 * - `arca`    → a arca (uma CAIXA retangular, não um barquinho) contra um ônibus e
 *               um campo de futebol.
 * - `golias`  → Golias contra uma pessoa de 1,75 m e uma porta de 2,10 m.
 * - `mar`     → o mar de fundição sobre os doze touros, e os 44.000 litros em
 *               caixas d'água de mil litros.
 * - `efa`     → os gômeres de 2,2 L enchendo a efa; a efa empata com o bato.
 * - `estadio` → o MAPA de Jerusalém a Emaús: o slider caminha e a distância
 *               percorrida acompanha.
 *
 * Regra de composição: nenhum rótulo é escrito solto por cima do desenho — todos
 * saem em `etiqueta()`, numa cápsula opaca, ligada ao objeto por uma linha-guia.
 *
 * O estado vem inteiro do renderizador (`info`): a viz só consome.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  escurecer,
  etiqueta,
  infoDe,
  limitar,
  MATERIAIS,
  numeroDe,
  paleta,
  ptBR,
  retangulo,
  rodape,
  sombraDeChao,
  texto,
  textoDe,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

/** A estrada segue um pouco além de Emaús, para o slider poder passar do ponto. */
const ESTADIOS_MAX = 70;
const ESTADIOS_EMAUS = 60;

const medidas: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  /**
   * Figura humana em proporção de 7,5 cabeças — ombro, cintura, joelho e pé nos
   * lugares certos. `passo` anima a caminhada; `armado` põe elmo, escudo e lança,
   * porque Golias não pode ser uma silhueta qualquer.
   */
  function humano(
    ctx: CanvasRenderingContext2D,
    cx: number,
    baseY: number,
    h: number,
    opcoes: { readonly cor?: string; readonly armado?: boolean; readonly passo?: number } = {},
  ): void {
    const cor = opcoes.cor ?? paleta().azulClaro;
    const topo = baseY - h;
    const raioCabecaX = h * 0.049;
    const raioCabecaY = h * 0.063;
    const yCabeca = topo + raioCabecaY * 1.05;
    const yOmbro = topo + h * 0.2;
    const yQuadril = topo + h * 0.5;
    const yJoelho = topo + h * 0.735;
    const larguraOmbro = h * 0.115;
    const larguraQuadril = h * 0.082;

    const balanco = opcoes.passo === undefined ? 0 : Math.sin(opcoes.passo);
    const abertura = balanco * h * 0.085;

    sombraDeChao(ctx, cx, baseY, h * 0.13);

    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    // Pernas: a de trás sai mais escura, para dar profundidade.
    for (const lado of [-1, 1]) {
      const atras = lado * balanco < 0;
      ctx.strokeStyle = atras ? escurecer(cor) : cor;
      ctx.lineWidth = h * 0.072;
      ctx.beginPath();
      ctx.moveTo(cx + lado * larguraQuadril * 0.55, yQuadril);
      ctx.lineTo(cx + lado * larguraQuadril * 0.75 + abertura * lado * 0.5, yJoelho);
      ctx.lineTo(cx + lado * larguraQuadril * 0.8 + abertura * lado, baseY);
      ctx.stroke();
    }

    // Braços — balançam ao contrário das pernas.
    ctx.lineWidth = h * 0.052;
    for (const lado of [-1, 1]) {
      ctx.strokeStyle = lado * balanco > 0 ? escurecer(cor) : cor;
      ctx.beginPath();
      ctx.moveTo(cx + lado * larguraOmbro * 0.85, yOmbro + h * 0.02);
      ctx.lineTo(cx + lado * larguraOmbro * 1.05, yQuadril - h * 0.02);
      ctx.lineTo(cx + lado * larguraOmbro * 1.0 - abertura * lado * 0.7, yQuadril + h * 0.1);
      ctx.stroke();
    }

    // Tronco: ombros largos, cintura estreita.
    ctx.fillStyle = cor;
    ctx.beginPath();
    ctx.moveTo(cx - larguraOmbro, yOmbro);
    ctx.quadraticCurveTo(
      cx - larguraOmbro * 0.92,
      (yOmbro + yQuadril) / 2,
      cx - larguraQuadril,
      yQuadril,
    );
    ctx.lineTo(cx + larguraQuadril, yQuadril);
    ctx.quadraticCurveTo(
      cx + larguraOmbro * 0.92,
      (yOmbro + yQuadril) / 2,
      cx + larguraOmbro,
      yOmbro,
    );
    ctx.quadraticCurveTo(cx, yOmbro - h * 0.035, cx - larguraOmbro, yOmbro);
    ctx.fill();

    // Pescoço e cabeça.
    retangulo(ctx, cx - h * 0.022, yCabeca + raioCabecaY * 0.5, h * 0.044, h * 0.06, h * 0.02, cor);
    ctx.fillStyle = cor;
    ctx.beginPath();
    ctx.ellipse(cx, yCabeca, raioCabecaX, raioCabecaY, 0, 0, Math.PI * 2);
    ctx.fill();

    if (opcoes.armado === true) {
      ctx.fillStyle = escurecer(cor, 0.35);
      ctx.beginPath();
      ctx.ellipse(
        cx,
        yCabeca - raioCabecaY * 0.15,
        raioCabecaX * 1.25,
        raioCabecaY * 0.95,
        0,
        Math.PI,
        0,
      );
      ctx.fill();

      // A crista do elmo.
      retangulo(
        ctx,
        cx - raioCabecaX * 0.18,
        topo - h * 0.045,
        raioCabecaX * 0.36,
        h * 0.055,
        h * 0.01,
        paleta().erro,
      );

      // A lança.
      ctx.strokeStyle = escurecer(cor, 0.35);
      ctx.lineWidth = h * 0.018;
      ctx.beginPath();
      ctx.moveTo(cx + larguraOmbro * 1.5, baseY);
      ctx.lineTo(cx + larguraOmbro * 1.15, topo - h * 0.06);
      ctx.stroke();

      // O escudo.
      ctx.fillStyle = escurecer(cor, 0.2);
      ctx.beginPath();
      ctx.ellipse(
        cx - larguraOmbro * 1.5,
        yQuadril - h * 0.06,
        h * 0.055,
        h * 0.085,
        0,
        0,
        Math.PI * 2,
      );
      ctx.fill();
    }
  }

  // ── Fase 1 · o côvado é o antebraço ───────────────────────────────────────

  /**
   * Antebraço desenhado no referencial do próprio braço: origem no cotovelo,
   * eixo +x na direção do dedo médio. Assim punho, palma, dedos e polegar caem
   * sozinhos no lugar, e a cota do côvado corre paralela ao osso.
   */
  function braco(
    ctx: CanvasRenderingContext2D,
    xCotovelo: number,
    yCotovelo: number,
    xDedo: number,
    yDedo: number,
  ): { angulo: number; comprimento: number; espessura: number } {
    const D = Math.hypot(xDedo - xCotovelo, yDedo - yCotovelo);
    const angulo = Math.atan2(yDedo - yCotovelo, xDedo - xCotovelo);
    // Meia-espessura: grossa no cotovelo, fina no punho.
    const w0 = D * 0.1;
    const w1 = D * 0.048;
    const xPunho = D * 0.7;
    const xPalma = D * 0.86;
    const wPalma = D * 0.066;

    // Braço (do ombro ao cotovelo), atrás de tudo.
    const xOmbro = xCotovelo - D * 0.14;
    const yOmbro = yCotovelo + D * 0.2;
    ctx.lineCap = 'round';
    ctx.strokeStyle = MATERIAIS.peleEscura;
    ctx.lineWidth = w0 * 2.25;
    ctx.beginPath();
    ctx.moveTo(xOmbro, yOmbro);
    ctx.lineTo(xCotovelo, yCotovelo);
    ctx.stroke();
    ctx.strokeStyle = MATERIAIS.pele;
    ctx.lineWidth = w0 * 2.05;
    ctx.beginPath();
    ctx.moveTo(xOmbro, yOmbro);
    ctx.lineTo(xCotovelo, yCotovelo);
    ctx.stroke();

    ctx.save();
    ctx.translate(xCotovelo, yCotovelo);
    ctx.rotate(angulo);

    const pele = ctx.createLinearGradient(0, -w0, 0, w0);
    pele.addColorStop(0, '#f6d3b0');
    pele.addColorStop(0.55, MATERIAIS.pele);
    pele.addColorStop(1, MATERIAIS.peleEscura);

    // Antebraço: barriga do músculo perto do cotovelo, afinando até o punho.
    ctx.beginPath();
    ctx.moveTo(-w0 * 0.2, -w0);
    ctx.quadraticCurveTo(D * 0.24, -w0 * 1.12, xPunho, -w1);
    ctx.lineTo(xPunho, w1);
    ctx.quadraticCurveTo(D * 0.24, w0 * 0.98, -w0 * 0.2, w0);
    ctx.closePath();
    ctx.fillStyle = pele;
    ctx.fill();
    ctx.strokeStyle = 'rgb(90 55 25 / 28%)';
    ctx.lineWidth = 1.2;
    ctx.stroke();

    // Polegar, saindo por baixo do punho.
    ctx.strokeStyle = MATERIAIS.peleEscura;
    ctx.lineCap = 'round';
    ctx.lineWidth = D * 0.05;
    ctx.beginPath();
    ctx.moveTo(xPunho + D * 0.01, wPalma * 0.5);
    ctx.quadraticCurveTo(xPalma, wPalma * 1.5, xPalma + D * 0.05, wPalma * 1.1);
    ctx.stroke();

    // Palma.
    ctx.beginPath();
    ctx.roundRect(xPunho - D * 0.01, -wPalma, xPalma - xPunho + D * 0.02, wPalma * 2, D * 0.03);
    ctx.fillStyle = pele;
    ctx.fill();
    ctx.strokeStyle = 'rgb(90 55 25 / 28%)';
    ctx.lineWidth = 1.2;
    ctx.stroke();

    // Quatro dedos; o médio é o que define o côvado — chega exatamente em D.
    const dedos = [
      { deslocamento: -wPalma * 0.72, fim: 0.955 },
      { deslocamento: -wPalma * 0.24, fim: 1.0 },
      { deslocamento: wPalma * 0.24, fim: 0.972 },
      { deslocamento: wPalma * 0.72, fim: 0.918 },
    ];
    for (const dedo of dedos) {
      const espessura = D * 0.028;
      ctx.beginPath();
      ctx.roundRect(
        xPalma - D * 0.02,
        dedo.deslocamento - espessura / 2,
        D * dedo.fim - xPalma + D * 0.02,
        espessura,
        espessura / 2,
      );
      ctx.fillStyle = pele;
      ctx.fill();
      ctx.strokeStyle = 'rgb(90 55 25 / 24%)';
      ctx.lineWidth = 1;
      ctx.stroke();

      retangulo(
        ctx,
        D * dedo.fim - espessura * 0.9,
        dedo.deslocamento - espessura * 0.3,
        espessura * 0.7,
        espessura * 0.6,
        espessura * 0.25,
        'rgb(255 255 255 / 55%)',
      );
    }

    // Vinco do cotovelo.
    ctx.strokeStyle = 'rgb(90 55 25 / 25%)';
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.arc(0, 0, w0 * 0.72, -1.1, 1.1);
    ctx.stroke();

    ctx.restore();
    return { angulo, comprimento: D, espessura: w0 };
  }

  function faseCovado(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const cor = paleta();
    const escolhido = textoDe(estado, 'escolhido');
    const certo = escolhido === 'antebraco';

    titulo(ctx, L, A, 'A régua está no seu braço');

    const xCotovelo = L * 0.26;
    const yCotovelo = A * 0.4;
    const xDedo = L * 0.8;
    const yDedo = A * 0.26;
    const { angulo, comprimento, espessura } = braco(ctx, xCotovelo, yCotovelo, xDedo, yDedo);

    // A cota do côvado corre PARALELA ao antebraço, acima dele.
    const corCota = escolhido === '' ? cor.azul : certo ? cor.verde : cor.trilho;
    const tamanho = limitar(A * 0.045, 10, 15);

    ctx.save();
    ctx.translate(xCotovelo, yCotovelo);
    ctx.rotate(angulo);

    const yCota = -(espessura + limitar(A * 0.075, 16, 34));
    ctx.strokeStyle = corCota;
    ctx.lineWidth = 1.8;
    ctx.lineCap = 'butt';
    ctx.beginPath();
    ctx.moveTo(0, yCota);
    ctx.lineTo(comprimento, yCota);
    ctx.moveTo(0, yCota - 7);
    ctx.lineTo(0, yCota + 7);
    ctx.moveTo(comprimento, yCota - 7);
    ctx.lineTo(comprimento, yCota + 7);
    ctx.stroke();

    ctx.setLineDash([3, 4]);
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(0, yCota + 7);
    ctx.lineTo(0, -espessura);
    ctx.moveTo(comprimento, yCota + 7);
    ctx.lineTo(comprimento, -espessura * 0.3);
    ctx.stroke();
    ctx.setLineDash([]);

    etiqueta(ctx, 'côvado — 44,5 cm', comprimento / 2, yCota, tamanho, corCota, 800);
    ctx.restore();

    // Os dois nomes das pontas, fora do desenho e ligados por linha-guia.
    etiqueta(
      ctx,
      'cotovelo',
      xCotovelo + L * 0.02,
      yCotovelo + A * 0.13,
      limitar(A * 0.04, 9, 13),
      cor.fraco,
      700,
      { alvo: [xCotovelo, yCotovelo] },
    );
    etiqueta(
      ctx,
      'ponta do dedo médio',
      xDedo - L * 0.04,
      yDedo + A * 0.15,
      limitar(A * 0.04, 9, 13),
      cor.fraco,
      700,
      { alvo: [xDedo, yDedo] },
    );

    // As três medidas do corpo na MESMA escala e no mesmo eixo — é a comparação
    // lado a lado que mostra por que o côvado não é o pé nem o passo.
    const xRegua = L * 0.36;
    // 75 cm ocupam a faixa útil.
    const escala = (L * 0.5) / 75;
    const alturaBarra = limitar(A * 0.045, 6, 14);
    const regua = [
      { id: 'pe', rotulo: 'pé — 25 cm', cm: 25 },
      { id: 'antebraco', rotulo: 'côvado — 44,5 cm', cm: 44.5 },
      { id: 'passo', rotulo: 'passo — 75 cm', cm: 75 },
    ];

    let yRegua = A * 0.68;
    for (const item of regua) {
      const marcado = escolhido === item.id;
      const bom = item.id === 'antebraco';

      retangulo(
        ctx,
        xRegua,
        yRegua,
        item.cm * escala,
        alturaBarra,
        3,
        marcado ? (bom ? cor.verde : cor.erro) : bom && certo ? cor.verde : cor.trilho,
      );
      texto(ctx, item.rotulo, xRegua - 10, yRegua + alturaBarra / 2, limitar(A * 0.04, 9, 12), {
        cor: marcado ? (bom ? cor.verde : cor.erro) : cor.fraco,
        peso: marcado || bom ? 800 : 500,
        alinhamento: 'right',
      });
      yRegua += alturaBarra * 1.5;
    }

    const aviso =
      escolhido === ''
        ? 'Escolha de onde vem a medida.'
        : certo
          ? 'Do cotovelo à ponta do dedo: 44,5 cm. ✔'
          : 'Essa medida não é o côvado — compare os tamanhos.';

    texto(ctx, aviso, L / 2, A * 0.95, limitar(A * 0.048, 10, 15), {
      cor: certo ? cor.verde : escolhido === '' ? cor.fraco : cor.erro,
      peso: 700,
    });
  }

  // ── Fase 2 · a arca contra coisas conhecidas ──────────────────────────────

  function iconeOnibus(
    ctx: CanvasRenderingContext2D,
    x: number,
    y: number,
    w: number,
    h: number,
  ): void {
    const corpo = h * 0.62;
    retangulo(ctx, x, y + h * 0.08, w, corpo, h * 0.14, '#e8b33a', '#a97f18', 1.2);
    retangulo(ctx, x + w * 0.08, y + h * 0.18, w * 0.5, corpo * 0.42, h * 0.06, '#7ec4f2');
    retangulo(ctx, x + w * 0.64, y + h * 0.18, w * 0.26, corpo * 0.42, h * 0.06, '#7ec4f2');

    ctx.fillStyle = '#3a3f52';
    for (const roda of [x + w * 0.24, x + w * 0.78]) {
      ctx.beginPath();
      ctx.arc(roda, y + h * 0.76, h * 0.15, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  function iconeCampo(
    ctx: CanvasRenderingContext2D,
    x: number,
    y: number,
    w: number,
    h: number,
  ): void {
    retangulo(ctx, x, y + h * 0.12, w, h * 0.72, 2, MATERIAIS.grama);

    // As faixas do gramado cortado.
    ctx.save();
    ctx.globalAlpha = 0.18;
    ctx.fillStyle = '#ffffff';
    for (let i = 0; i < 4; i++) ctx.fillRect(x + (w / 4) * i, y + h * 0.12, w / 8, h * 0.72);
    ctx.restore();

    ctx.strokeStyle = 'rgb(255 255 255 / 90%)';
    ctx.lineWidth = 1;
    ctx.strokeRect(x + 2, y + h * 0.12 + 2, w - 4, h * 0.72 - 4);
    ctx.beginPath();
    ctx.moveTo(x + w / 2, y + h * 0.12);
    ctx.lineTo(x + w / 2, y + h * 0.84);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(x + w / 2, y + h * 0.48, h * 0.16, 0, Math.PI * 2);
    ctx.stroke();
  }

  /**
   * A arca era uma CAIXA retangular projetada para flutuar — não o barquinho de
   * proa curva que as pinturas religiosas mostram. O ícone insiste nisso.
   */
  function iconeArca(
    ctx: CanvasRenderingContext2D,
    x: number,
    y: number,
    w: number,
    h: number,
  ): void {
    const casco = h * 0.5;
    const yCasco = y + h * 0.4;

    retangulo(ctx, x, yCasco, w, casco, 1.5, MATERIAIS.madeira, 'rgb(0 0 0 / 25%)', 1);
    ctx.strokeStyle = 'rgb(0 0 0 / 16%)';
    ctx.lineWidth = 0.8;
    for (let i = 1; i < 3; i++) {
      ctx.beginPath();
      ctx.moveTo(x, yCasco + (casco / 3) * i);
      ctx.lineTo(x + w, yCasco + (casco / 3) * i);
      ctx.stroke();
    }

    // Cobertura reta, com a porta lateral e a fileira de aberturas.
    retangulo(
      ctx,
      x + w * 0.1,
      y + h * 0.08,
      w * 0.8,
      h * 0.32,
      1.5,
      MATERIAIS.madeiraClara,
      'rgb(0 0 0 / 22%)',
      1,
    );
    ctx.fillStyle = 'rgb(0 0 0 / 35%)';
    for (let i = 0; i < 5; i++) {
      ctx.fillRect(x + w * (0.18 + i * 0.15), y + h * 0.17, w * 0.05, h * 0.1);
    }
    retangulo(
      ctx,
      x + w * 0.42,
      yCasco + casco * 0.25,
      w * 0.14,
      casco * 0.6,
      1,
      'rgb(0 0 0 / 45%)',
    );
  }

  /**
   * A arca que VOCÊ está medindo: a mesma caixa, mas em planta — traço tracejado
   * e uma régua embaixo. Distingue a linha do slider da arca de Noé, já pronta.
   */
  function iconeProjeto(
    ctx: CanvasRenderingContext2D,
    x: number,
    y: number,
    w: number,
    h: number,
    cor: string,
  ): void {
    ctx.save();
    ctx.strokeStyle = cor;
    ctx.lineWidth = 1.6;
    ctx.setLineDash([3, 2]);
    ctx.strokeRect(x + 1, y + h * 0.24, w - 2, h * 0.36);
    ctx.setLineDash([]);
    ctx.strokeRect(x + w * 0.12, y + h * 0.1, w * 0.76, h * 0.14);

    // Régua de medição sob o casco.
    ctx.beginPath();
    ctx.moveTo(x, y + h * 0.76);
    ctx.lineTo(x + w, y + h * 0.76);
    for (let i = 0; i <= 4; i++) {
      const tx = x + (w / 4) * i;
      ctx.moveTo(tx, y + h * 0.7);
      ctx.lineTo(tx, y + h * 0.82);
    }
    ctx.stroke();
    ctx.restore();
  }

  function faseArca(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const metros = numeroDe(info, 'metros', 0);
    const ok = info.ok === true;

    titulo(ctx, L, A, 'A arca ao lado do que você conhece');

    // Escala fixa: 140 m ocupam a faixa útil.
    const xIcone = L * 0.03;
    const wIcone = L * 0.085;
    const x0 = L * 0.135;
    const largura = L * 0.83;
    const unidade = largura / 140;

    const linhas = [
      { rotulo: 'ônibus urbano', m: 12, cor: '#e8b33a', icone: 'onibus', destaque: false },
      { rotulo: 'campo de futebol', m: 105, cor: MATERIAIS.grama, icone: 'campo', destaque: false },
      {
        rotulo: 'arca de Noé — 300 côvados',
        m: 133.5,
        cor: MATERIAIS.madeira,
        icone: 'arca',
        destaque: false,
      },
      {
        rotulo: 'sua arca',
        m: metros,
        cor: ok ? cor.verde : cor.ouro,
        icone: 'projeto',
        destaque: true,
      },
    ];

    const passo = (A * 0.6) / linhas.length;
    const altura = passo * 0.6;
    let y = A * 0.17;

    for (const linha of linhas) {
      const w = Math.min(linha.m * unidade, largura);

      if (linha.icone === 'onibus')
        iconeOnibus(ctx, xIcone, y - altura * 0.1, wIcone, altura * 1.15);
      else if (linha.icone === 'campo')
        iconeCampo(ctx, xIcone, y - altura * 0.1, wIcone, altura * 1.15);
      else if (linha.icone === 'projeto')
        iconeProjeto(ctx, xIcone, y - altura * 0.1, wIcone, altura * 1.15, linha.cor);
      else iconeArca(ctx, xIcone, y - altura * 0.1, wIcone, altura * 1.15);

      retangulo(ctx, x0, y, largura, altura, 4, cor.fundo, cor.trilho, 1);
      retangulo(ctx, x0, y, Math.max(w, 2), altura, 4, linha.cor);

      // Barra longa: rótulo em branco DENTRO dela. Barra curta: depois dela, sobre
      // o trilho — senão o texto some em cima da própria barra.
      const dentro = w > largura * 0.35;
      texto(
        ctx,
        linha.rotulo,
        dentro ? x0 + 8 : x0 + Math.max(w, 2) + 8,
        y + altura / 2,
        limitar(A * 0.042, 9, 13),
        {
          cor: dentro ? '#ffffff' : cor.texto,
          peso: linha.destaque ? 800 : 600,
          alinhamento: 'left',
        },
      );
      // O valor fica no fim da BARRA quando ela é longa, e no fim do trilho quando
      // é curta — nunca metade sobre cada fundo.
      texto(
        ctx,
        `${linha.m.toString().replace('.', ',')} m`,
        (dentro ? x0 + w : x0 + largura) - 8,
        y + altura / 2,
        limitar(A * 0.042, 9, 13),
        { cor: dentro ? '#ffffff' : cor.fraco, peso: 700, alinhamento: 'right' },
      );

      y += passo;
    }

    texto(
      ctx,
      `${Math.round(numeroDe(info, 'covados', 0))} côvados`,
      L / 2,
      A * 0.845,
      limitar(A * 0.07, 15, 24),
      { cor: ok ? cor.verde : cor.texto, peso: 800 },
    );
    texto(ctx, 'alvo: 300 côvados', L / 2, A * 0.9, limitar(A * 0.042, 9, 13), {
      cor: cor.fraco,
      peso: 600,
    });

    rodape(
      ctx,
      L,
      A,
      ok,
      '133,5 m — mais comprida que um campo de futebol. ✔',
      'Ajuste até os 300 côvados fecharem.',
    );
  }

  // ── Fase 3 · Golias ao lado de uma pessoa e de uma porta ──────────────────
  function faseGolias(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const cm = numeroDe(info, 'altura', 200);
    const ok = info.ok === true;

    titulo(ctx, L, A, 'Golias ao lado de uma pessoa');

    // 330 cm ocupam a altura útil da cena.
    const chao = A * 0.82;
    const topo = A * 0.17;
    const unidade = (chao - topo) / 330;

    const solo = ctx.createLinearGradient(0, chao - 4, 0, chao + A * 0.05);
    solo.addColorStop(0, '#dfe5f4');
    solo.addColorStop(1, cor.fundo);
    ctx.fillStyle = solo;
    ctx.fillRect(0, chao, L, A * 0.05);
    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(L * 0.04, chao);
    ctx.lineTo(L * 0.96, chao);
    ctx.stroke();

    // Porta comum de 2,10 m como terceira referência.
    const xPorta = L * 0.66;
    const wPorta = limitar(L * 0.11, 34, 96);
    const hPorta = 210 * unidade;

    retangulo(
      ctx,
      xPorta - wPorta * 0.06,
      chao - hPorta - wPorta * 0.06,
      wPorta * 1.12,
      hPorta + wPorta * 0.06,
      3,
      '#d7ddef',
    );
    retangulo(ctx, xPorta, chao - hPorta, wPorta, hPorta, 2, '#ffffff', MATERIAIS.cinza, 1.5);
    retangulo(
      ctx,
      xPorta + wPorta * 0.12,
      chao - hPorta * 0.9,
      wPorta * 0.76,
      hPorta * 0.36,
      2,
      '#f2f5fc',
      cor.trilho,
      1,
    );
    retangulo(
      ctx,
      xPorta + wPorta * 0.12,
      chao - hPorta * 0.48,
      wPorta * 0.76,
      hPorta * 0.36,
      2,
      '#f2f5fc',
      cor.trilho,
      1,
    );
    ctx.fillStyle = cor.ouro;
    ctx.beginPath();
    ctx.arc(
      xPorta + wPorta * 0.86,
      chao - hPorta * 0.45,
      Math.max(wPorta * 0.05, 2),
      0,
      Math.PI * 2,
    );
    ctx.fill();

    etiqueta(
      ctx,
      'porta 2,10 m',
      xPorta + wPorta / 2,
      chao - hPorta - limitar(A * 0.055, 12, 22),
      limitar(A * 0.04, 9, 12),
    );

    humano(ctx, L * 0.22, chao, 175 * unidade, { cor: cor.azulClaro });
    etiqueta(
      ctx,
      'pessoa 1,75 m',
      L * 0.22,
      chao + limitar(A * 0.05, 11, 18),
      limitar(A * 0.04, 9, 13),
    );

    const corGolias = ok ? cor.verde : cor.ouro;
    humano(ctx, L * 0.44, chao, cm * unidade, { cor: corGolias, armado: true });
    etiqueta(
      ctx,
      'Golias',
      L * 0.44,
      chao + limitar(A * 0.05, 11, 18),
      limitar(A * 0.04, 9, 13),
      corGolias,
    );

    // Cota vertical da altura escolhida.
    const xCota = L * 0.55;
    const yTopo = chao - cm * unidade;
    ctx.strokeStyle = corGolias;
    ctx.lineWidth = 1.8;
    ctx.beginPath();
    ctx.moveTo(xCota, yTopo);
    ctx.lineTo(xCota, chao);
    ctx.moveTo(xCota - 6, yTopo);
    ctx.lineTo(xCota + 6, yTopo);
    ctx.moveTo(xCota - 6, chao);
    ctx.lineTo(xCota + 6, chao);
    ctx.stroke();

    etiqueta(
      ctx,
      `${(cm / 100).toFixed(2).replace('.', ',')} m`,
      xCota,
      (yTopo + chao) / 2,
      limitar(A * 0.048, 11, 16),
      corGolias,
      800,
    );

    texto(
      ctx,
      '6 côvados + 1 palmo = 6 × 44,5 + 22,2',
      L / 2,
      A * 0.94,
      limitar(A * 0.045, 10, 14),
      { cor: ok ? cor.verde : cor.fraco, peso: 700 },
    );
  }

  // ── Fase 4 · os 44.000 litros do "mar" em caixas d'água ───────────────────

  /** Caixa d'água comum: corpo levemente cônico, tampa e nível de água. */
  function caixaDagua(
    ctx: CanvasRenderingContext2D,
    x: number,
    y: number,
    w: number,
    h: number,
    cheia: boolean,
  ): void {
    const cor = paleta();
    const inclinacao = w * 0.08;

    ctx.beginPath();
    ctx.moveTo(x + inclinacao, y + h * 0.14);
    ctx.lineTo(x + w - inclinacao, y + h * 0.14);
    ctx.lineTo(x + w, y + h);
    ctx.lineTo(x, y + h);
    ctx.closePath();
    ctx.fillStyle = cheia ? cor.azulClaro : '#ffffff';
    ctx.fill();
    ctx.strokeStyle = cheia ? '#2a7fcc' : cor.trilho;
    ctx.lineWidth = 1.1;
    ctx.stroke();

    retangulo(
      ctx,
      x - w * 0.04,
      y + h * 0.02,
      w * 1.08,
      h * 0.14,
      w * 0.06,
      cheia ? '#2a7fcc' : '#e6eaf6',
      cor.trilho,
      0.8,
    );
  }

  function faseMar(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const litros = numeroDe(info, 'litros', 0);
    const ok = info.ok === true;

    titulo(ctx, L, A, 'O “mar de fundição” em caixas d’água');

    // À esquerda, a peça do templo: bacia de cobre sobre os doze touros.
    const bx = L * 0.17;
    const by = A * 0.32;
    const br = limitar(Math.min(L * 0.12, A * 0.17), 26, 96);

    const bronze = ctx.createLinearGradient(bx - br, 0, bx + br, 0);
    bronze.addColorStop(0, '#7d4f1c');
    bronze.addColorStop(0.45, MATERIAIS.bronze);
    bronze.addColorStop(1, '#8a5a22');

    ctx.beginPath();
    ctx.moveTo(bx - br, by);
    ctx.quadraticCurveTo(bx - br * 0.9, by + br * 1.15, bx, by + br * 1.15);
    ctx.quadraticCurveTo(bx + br * 0.9, by + br * 1.15, bx + br, by);
    ctx.closePath();
    ctx.fillStyle = bronze;
    ctx.fill();
    ctx.strokeStyle = 'rgb(0 0 0 / 28%)';
    ctx.lineWidth = 1.5;
    ctx.stroke();

    ctx.fillStyle = 'rgb(58 160 255 / 55%)';
    ctx.beginPath();
    ctx.ellipse(bx, by, br * 0.94, br * 0.2, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#c98c33';
    ctx.lineWidth = limitar(br * 0.09, 2, 7);
    ctx.beginPath();
    ctx.ellipse(bx, by, br, br * 0.22, 0, 0, Math.PI * 2);
    ctx.stroke();

    // Os doze touros: alguns de frente, o resto sugerido atrás.
    for (let i = 0; i < 5; i++) {
      const tx = bx - br * 0.7 + ((br * 1.4) / 4) * i;
      const ty = by + br * 1.15;
      const corTouro = i % 2 ? '#8a5a22' : MATERIAIS.bronze;

      retangulo(ctx, tx - br * 0.13, ty, br * 0.26, br * 0.34, br * 0.08, corTouro);
      ctx.fillStyle = corTouro;
      ctx.beginPath();
      ctx.arc(tx, ty + br * 0.34, br * 0.11, 0, Math.PI * 2);
      ctx.fill();
    }

    etiqueta(ctx, 'o “mar” — 2.000 batos', bx, by + br * 1.75, limitar(A * 0.04, 9, 13));

    // Uma caixa desenhada = 1.000 litros; a grade mostra até 44 (o alvo).
    const cheias = Math.min(Math.round(litros / 1000), 44);
    const colunas = 11;
    const linhas = 4;
    const gx = L * 0.37;
    const gw = L * 0.58;
    const gy = A * 0.2;
    const gh = A * 0.4;
    const cw = gw / colunas;
    const ch = gh / linhas;

    for (let i = 0; i < colunas * linhas; i++) {
      caixaDagua(
        ctx,
        gx + (i % colunas) * cw,
        gy + Math.floor(i / colunas) * ch,
        cw * 0.74,
        ch * 0.76,
        i < cheias,
      );
    }

    texto(
      ctx,
      `cada caixa = 1.000 litros · ${cheias} de 44 cheias`,
      gx + gw / 2,
      gy + gh + A * 0.03,
      limitar(A * 0.04, 9, 13),
      { cor: cor.fraco, peso: 600 },
    );

    texto(
      ctx,
      `${ptBR(Math.round(numeroDe(info, 'batos', 0)))} batos`,
      L / 2,
      A * 0.78,
      limitar(A * 0.075, 15, 25),
      { cor: ok ? cor.verde : cor.texto, peso: 800 },
    );
    texto(
      ctx,
      `${ptBR(litros)} L ÷ 22 L por bato · alvo: 2.000 batos`,
      L / 2,
      A * 0.87,
      limitar(A * 0.042, 9, 13),
      { cor: cor.fraco, peso: 600 },
    );

    rodape(
      ctx,
      L,
      A,
      ok,
      '44.000 litros — 44 caixas d’água cheias. ✔',
      'Ajuste até dar 2.000 batos.',
    );
  }

  // ── Fase 5 · os gômeres enchendo a efa ────────────────────────────────────

  /** Vaso de barro: bojo largo, boca estreita, pé. Serve de silhueta e de recorte. */
  function vaso(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number): void {
    ctx.beginPath();
    ctx.moveTo(x + w * 0.28, y);
    ctx.lineTo(x + w * 0.72, y);
    ctx.quadraticCurveTo(x + w * 0.78, y + h * 0.1, x + w * 0.88, y + h * 0.22);
    ctx.quadraticCurveTo(x + w, y + h * 0.5, x + w * 0.86, y + h * 0.82);
    ctx.quadraticCurveTo(x + w * 0.78, y + h, x + w * 0.6, y + h);
    ctx.lineTo(x + w * 0.4, y + h);
    ctx.quadraticCurveTo(x + w * 0.22, y + h, x + w * 0.14, y + h * 0.82);
    ctx.quadraticCurveTo(x, y + h * 0.5, x + w * 0.12, y + h * 0.22);
    ctx.quadraticCurveTo(x + w * 0.22, y + h * 0.1, x + w * 0.28, y);
    ctx.closePath();
  }

  function faseEfa(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const gomores = numeroDe(info, 'gomores', 0);
    const ok = info.ok === true;

    titulo(ctx, L, A, 'O gômer de maná dentro da efa');

    const topo = A * 0.2;
    const baixo = A * 0.74;
    const altura = baixo - topo;
    const largura = L * 0.24;
    const fracao = limitar((gomores * 2.2) / 22, 0, 1.2);

    // A efa, com o maná subindo conforme os gômeres entram.
    const x = L * 0.12;
    vaso(ctx, x, topo, largura, altura);
    ctx.fillStyle = '#efe3d2';
    ctx.fill();

    ctx.save();
    vaso(ctx, x, topo, largura, altura);
    ctx.clip();
    const nivel = topo + altura * (1 - Math.min(fracao, 1));
    // Passar de 22 L transborda: vermelho diz isso sem uma linha de texto.
    ctx.fillStyle = fracao > 1 ? cor.erro : cor.ouro;
    ctx.fillRect(x, nivel, largura, baixo - nivel);
    ctx.fillStyle = 'rgb(255 255 255 / 35%)';
    for (let i = 0; i < 90; i++) {
      const gx = x + (((i * 37) % 100) / 100) * largura;
      const gy = nivel + (((i * 53) % 100) / 100) * (baixo - nivel);
      ctx.beginPath();
      ctx.arc(gx, gy, Math.max(largura * 0.012, 1), 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();

    vaso(ctx, x, topo, largura, altura);
    ctx.strokeStyle = MATERIAIS.madeira;
    ctx.lineWidth = 2.5;
    ctx.stroke();

    etiqueta(
      ctx,
      'efa — 22 L',
      x + largura / 2,
      baixo + limitar(A * 0.06, 13, 22),
      limitar(A * 0.045, 10, 14),
      cor.texto,
      800,
    );
    etiqueta(
      ctx,
      'medida dos secos',
      x + largura / 2,
      topo - limitar(A * 0.045, 10, 16),
      limitar(A * 0.038, 9, 12),
    );

    // Régua dos dez gômeres, ao lado do vaso.
    for (let i = 0; i < 10; i++) {
      const yy = baixo - altura * ((i + 1) / 10);
      ctx.strokeStyle = i < gomores ? cor.ouro : cor.trilho;
      ctx.lineWidth = i < gomores ? 2.2 : 1.4;
      ctx.beginPath();
      ctx.moveTo(x + largura * 0.94, yy);
      ctx.lineTo(x + largura + L * 0.035, yy);
      ctx.stroke();
    }
    texto(
      ctx,
      `${Math.min(gomores, 10)}/10`,
      x + largura + L * 0.045,
      topo + altura * 0.06,
      limitar(A * 0.04, 9, 13),
      { cor: cor.ouro, peso: 800, alinhamento: 'left' },
    );

    // O bato ao lado: mesma capacidade, outra família de medidas.
    const xBato = L * 0.6;
    vaso(ctx, xBato, topo, largura, altura);
    ctx.fillStyle = '#e9eef9';
    ctx.fill();

    if (ok) {
      ctx.save();
      vaso(ctx, xBato, topo, largura, altura);
      ctx.clip();
      ctx.fillStyle = 'rgb(58 160 255 / 45%)';
      ctx.fillRect(xBato, topo, largura, altura);
      ctx.restore();
    }

    vaso(ctx, xBato, topo, largura, altura);
    ctx.strokeStyle = ok ? cor.azul : MATERIAIS.cinza;
    ctx.lineWidth = 2.5;
    ctx.stroke();

    etiqueta(
      ctx,
      'bato — 22 L',
      xBato + largura / 2,
      baixo + limitar(A * 0.06, 13, 22),
      limitar(A * 0.045, 10, 14),
      ok ? cor.azul : cor.texto,
      800,
    );
    etiqueta(
      ctx,
      ok ? 'a mesma capacidade' : 'medida dos líquidos',
      xBato + largura / 2,
      topo - limitar(A * 0.045, 10, 16),
      limitar(A * 0.038, 9, 12),
      ok ? cor.verde : cor.fraco,
    );

    texto(
      ctx,
      `${gomores} × 2,2 L = ${(gomores * 2.2).toFixed(1).replace('.', ',')} L`,
      L / 2,
      A * 0.87,
      limitar(A * 0.058, 13, 20),
      { cor: ok ? cor.verde : cor.texto, peso: 800 },
    );

    rodape(
      ctx,
      L,
      A,
      ok,
      'Dez gômeres numa efa — e a efa empata com o bato. ✔',
      'Encha a efa: quantos gômeres cabem?',
    );
  }

  // ── Fase 6 · o mapa de Jerusalém a Emaús ──────────────────────────────────
  //
  // Uma régua não diz nada sobre uma caminhada. O mapa diz: a estrada sobe e
  // desce, Emaús aparece a 60 estádios do portão, e o slider LEVA os dois
  // discípulos por ela — a distância percorrida é lida do próprio trajeto.

  /**
   * Amostra a estrada (uma bézier cúbica) e monta a tabela de comprimento de
   * arco. É ela que faz o caminhante andar a passo constante: avançar pelo
   * parâmetro da curva o faria acelerar nas retas e frear nas voltas.
   */
  function estrada(
    L: number,
    A: number,
  ): {
    pontos: [number, number][];
    em(fracao: number): [number, number];
  } {
    const p0: [number, number] = [L * 0.11, A * 0.72];
    const p3: [number, number] = [L * 0.9, A * 0.35];
    const c1: [number, number] = [L * 0.32, A * 0.44];
    const c2: [number, number] = [L * 0.62, A * 0.86];

    const pontos: [number, number][] = [];
    for (let i = 0; i <= 160; i++) {
      const u = i / 160;
      const v = 1 - u;
      pontos.push([
        v * v * v * p0[0] + 3 * v * v * u * c1[0] + 3 * v * u * u * c2[0] + u * u * u * p3[0],
        v * v * v * p0[1] + 3 * v * v * u * c1[1] + 3 * v * u * u * c2[1] + u * u * u * p3[1],
      ]);
    }

    const acumulado = [0];
    for (let i = 1; i < pontos.length; i++) {
      const atual = pontos[i];
      const anterior = pontos[i - 1];
      if (atual === undefined || anterior === undefined) continue;
      acumulado.push(
        (acumulado[i - 1] ?? 0) + Math.hypot(atual[0] - anterior[0], atual[1] - anterior[1]),
      );
    }
    const total = acumulado[acumulado.length - 1] ?? 1;

    const em = (fracao: number): [number, number] => {
      const alvo = limitar(fracao, 0, 1) * total;
      let i = 1;
      while (i < acumulado.length - 1 && (acumulado[i] ?? 0) < alvo) i++;

      const anterior = pontos[i - 1] ?? p0;
      const atual = pontos[i] ?? p3;
      const k =
        (alvo - (acumulado[i - 1] ?? 0)) /
        Math.max((acumulado[i] ?? 0) - (acumulado[i - 1] ?? 0), 1e-6);

      return [
        anterior[0] + (atual[0] - anterior[0]) * k,
        anterior[1] + (atual[1] - anterior[1]) * k,
      ];
    };

    return { pontos, em };
  }

  function tracar(
    ctx: CanvasRenderingContext2D,
    pontos: readonly [number, number][],
    ate: number,
    cor: string,
    largura: number,
  ): void {
    const inicio = pontos[0];
    if (inicio === undefined) return;

    ctx.strokeStyle = cor;
    ctx.lineWidth = largura;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.beginPath();
    ctx.moveTo(inicio[0], inicio[1]);

    const n = Math.max(Math.round(ate * (pontos.length - 1)), 1);
    for (let i = 1; i <= n; i++) {
      const p = pontos[i];
      if (p !== undefined) ctx.lineTo(p[0], p[1]);
    }
    ctx.stroke();
  }

  function cidade(
    ctx: CanvasRenderingContext2D,
    cx: number,
    cy: number,
    escala: number,
    grande: boolean,
  ): void {
    const w = escala * (grande ? 2.6 : 1.7);
    const h = escala * (grande ? 1.15 : 0.8);

    sombraDeChao(ctx, cx, cy + h * 0.52, w * 0.5, 0.12);
    retangulo(ctx, cx - w / 2, cy - h * 0.5, w, h, escala * 0.08, '#e5dcc6', '#a89a7c', 1.4);

    const torres = grande ? 4 : 3;
    for (let i = 0; i < torres; i++) {
      const tx = cx - w / 2 + (w / torres) * (i + 0.5);
      const th = h * (grande ? 0.8 : 0.6) * (i % 2 ? 0.75 : 1);

      retangulo(
        ctx,
        tx - escala * 0.2,
        cy - h * 0.5 - th,
        escala * 0.4,
        th,
        escala * 0.05,
        '#efe7d4',
        '#a89a7c',
        1.2,
      );
      ctx.fillStyle = '#b1663f';
      ctx.beginPath();
      ctx.moveTo(tx - escala * 0.28, cy - h * 0.5 - th);
      ctx.lineTo(tx + escala * 0.28, cy - h * 0.5 - th);
      ctx.lineTo(tx, cy - h * 0.5 - th - escala * 0.26);
      ctx.closePath();
      ctx.fill();
    }

    // Portão.
    ctx.fillStyle = MATERIAIS.madeira;
    ctx.beginPath();
    ctx.roundRect(cx - escala * 0.16, cy - h * 0.06, escala * 0.32, h * 0.56, [
      escala * 0.16,
      escala * 0.16,
      0,
      0,
    ]);
    ctx.fill();
  }

  function oliveira(ctx: CanvasRenderingContext2D, x: number, y: number, escala: number): void {
    ctx.strokeStyle = '#7a5c3a';
    ctx.lineWidth = Math.max(escala * 0.14, 1.2);
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x, y - escala * 0.7);
    ctx.stroke();

    ctx.fillStyle = MATERIAIS.gramaEscura;
    ctx.beginPath();
    ctx.ellipse(x, y - escala, escala * 0.62, escala * 0.5, 0, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = 'rgb(255 255 255 / 16%)';
    ctx.beginPath();
    ctx.ellipse(
      x - escala * 0.15,
      y - escala * 1.15,
      escala * 0.3,
      escala * 0.22,
      0,
      0,
      Math.PI * 2,
    );
    ctx.fill();
  }

  function faseEstadio(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const estadios = limitar(numeroDe(info, 'estadios', 0), 0, ESTADIOS_MAX);
    const km = (estadios * 185) / 1000;
    const ok = info.ok === true;

    titulo(ctx, L, A, 'De Jerusalém a Emaús — caminhe com eles');

    // Colinas ao fundo: a estrada de Jerusalém desce por vales.
    for (const colina of [
      { y: 0.42, amplitude: 0.11, cor: '#cfe0cf' },
      { y: 0.5, amplitude: 0.09, cor: '#bcd7bd' },
    ]) {
      ctx.fillStyle = colina.cor;
      ctx.beginPath();
      ctx.moveTo(0, A * (colina.y + colina.amplitude));
      for (let x = 0; x <= L; x += L / 24) {
        ctx.lineTo(
          x,
          A * colina.y + Math.sin(x / (L / 7) + colina.y * 9) * A * colina.amplitude * 0.5,
        );
      }
      ctx.lineTo(L, A * 0.9);
      ctx.lineTo(0, A * 0.9);
      ctx.closePath();
      ctx.fill();
    }

    // Vegetação — vai antes da estrada, que passa por cima dela.
    const escalaArvore = limitar(A * 0.035, 7, 16);
    for (const posicao of [
      [0.22, 0.72],
      [0.4, 0.66],
      [0.63, 0.62],
      [0.83, 0.5],
      [0.12, 0.5],
      [0.52, 0.4],
    ]) {
      oliveira(ctx, L * (posicao[0] ?? 0), A * (posicao[1] ?? 0), escalaArvore);
    }

    const { pontos, em } = estrada(L, A);
    const largura = limitar(A * 0.03, 6, 13);

    // Estrada de terra: borda, leito e o trecho JÁ CAMINHADO por cima.
    tracar(ctx, pontos, 1, '#b9a074', largura + 4);
    tracar(ctx, pontos, 1, MATERIAIS.terra, largura);
    const fracao = estadios / ESTADIOS_MAX;
    if (estadios > 0) {
      tracar(ctx, pontos, fracao, ok ? cor.verde : cor.azulClaro, largura * 0.55);
    }

    // Marcos de dez em dez estádios.
    for (let i = 10; i <= ESTADIOS_MAX; i += 10) {
      const [mx, my] = em(i / ESTADIOS_MAX);
      const alcancado = estadios >= i;

      retangulo(
        ctx,
        mx - 2,
        my - largura * 1.5,
        4,
        largura * 0.95,
        1.5,
        alcancado ? (ok ? cor.verde : cor.azul) : MATERIAIS.cinza,
      );
      texto(ctx, `${i}`, mx, my - largura * 1.9, limitar(A * 0.032, 8, 11), {
        cor: alcancado ? cor.texto : cor.fraco,
        peso: 700,
      });
    }

    // As duas pontas do trajeto.
    const [jx, jy] = em(0);
    const [ex, ey] = em(ESTADIOS_EMAUS / ESTADIOS_MAX);

    cidade(ctx, jx, jy - largura * 1.2, limitar(A * 0.07, 14, 34), true);
    etiqueta(ctx, 'Jerusalém', jx, jy + largura * 1.6, limitar(A * 0.042, 9, 14), cor.texto, 800);
    cidade(ctx, ex, ey - largura * 1.1, limitar(A * 0.05, 10, 24), false);
    etiqueta(
      ctx,
      ok ? 'Emaús ✔' : 'Emaús — 60 estádios',
      ex,
      ey + largura * 1.6,
      limitar(A * 0.042, 9, 14),
      ok ? cor.verde : cor.texto,
      800,
    );

    // Os dois discípulos, no ponto exato do trajeto.
    const [cx, cy] = em(fracao);
    const altura = limitar(A * 0.1, 18, 44);
    // Param de andar ao chegar: a caminhada acabou.
    const passo = estadios > 0 && !ok ? t * 5 : 0;

    humano(ctx, cx - altura * 0.22, cy + largura * 0.1, altura * 0.94, {
      cor: '#6d5aa8',
      passo,
    });
    humano(ctx, cx + altura * 0.22, cy + largura * 0.1, altura, {
      cor: ok ? cor.verde : cor.azul,
      passo: passo + 1.6,
    });

    texto(
      ctx,
      `${estadios} ${estadios === 1 ? 'estádio' : 'estádios'} · ${km.toLocaleString('pt-BR', {
        maximumFractionDigits: 2,
      })} km`,
      L / 2,
      A * 0.845,
      limitar(A * 0.075, 15, 25),
      { cor: ok ? cor.verde : cor.texto, peso: 800 },
    );
    texto(
      ctx,
      `${estadios} × 185 m — Emaús fica a 60 estádios (11,1 km)`,
      L / 2,
      A * 0.9,
      limitar(A * 0.042, 9, 13),
      { cor: cor.fraco, peso: 600 },
    );

    rodape(
      ctx,
      L,
      A,
      ok,
      'Chegaram a Emaús — e ainda voltaram no mesmo dia. ✔',
      estadios > ESTADIOS_EMAUS
        ? 'Você passou do vilarejo — volte um pouco.'
        : 'Arraste para caminhar até Emaús.',
    );
  }

  const FASES: Readonly<
    Record<string, (ctx: CanvasRenderingContext2D, L: number, A: number, t: number) => void>
  > = {
    covado: faseCovado,
    arca: faseArca,
    golias: faseGolias,
    mar: faseMar,
    efa: faseEfa,
    estadio: faseEstadio,
  };

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => {
      const fase = textoDe(infoDe(estado), 'fase');
      (FASES[fase] ?? faseCovado)(ctx, L, A, t);
    },
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default medidas;
